// Illustrations generated by the narrator's model, requested on demand and cached per game.
// Until one arrives (or if drawing is off or fails), the hand-drawn icons stand in.

import { postJson } from './api.js';
import { settings, effectiveProvider } from './settings.js';
import { itemShape } from './grid.js';
import { alignmentOf, npcKey } from './state.js';

const MAX_PARALLEL = 2;
const queue = [];
const pending = new Set();
const failed = new Set();
let running = 0;
let disabledReason = null;
let hooks = { getGame: () => null, onReady: () => {}, onSave: () => {} };

export function initArt(options) {
  hooks = { ...hooks, ...options };
}

export const artKey = (kind, subject) => `${kind}:${npcKey(subject?.name)}`;

export function artUrl(kind, subject) {
  return hooks.getGame()?.art?.[artKey(kind, subject)] || null;
}

export const isPending = (kind, subject) => pending.has(artKey(kind, subject));

export function artEnabled() {
  const provider = effectiveProvider();
  return settings.illustrations && !disabledReason && (provider === 'anthropic' || provider === 'openai');
}

/** Asks for an illustration if there isn't one yet. Safe to call repeatedly. */
export function requestArt(kind, subject) {
  const game = hooks.getGame();
  if (!game || !subject?.name || !artEnabled()) return;
  const key = artKey(kind, subject);
  if (game.art?.[key] || pending.has(key) || failed.has(key)) return;
  pending.add(key);
  queue.push({ key, kind, subject: { ...subject } });
  pump();
}

function pump() {
  while (running < MAX_PARALLEL && queue.length) {
    const job = queue.shift();
    running += 1;
    run(job).finally(() => {
      running -= 1;
      pump();
    });
  }
}

async function run({ key, kind, subject }) {
  const shape = kind === 'item' ? itemShape(subject) : { w: 5, h: 6 };
  try {
    const { url } = await postJson('/api/art', {
      kind,
      name: subject.name,
      type: subject.type || '',
      description: subject.description || '',
      alignment: kind === 'npc' ? alignmentOf(subject) : undefined,
      w: shape.w,
      h: shape.h,
    });
    const game = hooks.getGame();
    if (!game) return;
    game.art = game.art || {};
    game.art[key] = url;
    hooks.onSave();
    hooks.onReady(key, url);
  } catch (error) {
    failed.add(key);
    // No drawing at all from this narrator (demo mode, or the key can't): stop asking.
    if (error.status === 501 || error.auth) disabledReason = error.message;
    console.warn(`[descend] no illustration for ${subject.name}: ${error.message}`);
  } finally {
    pending.delete(key);
  }
}

/** Forgets a broken image so the hand-drawn icon is used and it can be drawn again later. */
export function dropArt(url) {
  const game = hooks.getGame();
  if (!game?.art) return;
  for (const [key, value] of Object.entries(game.art)) {
    if (value === url) {
      delete game.art[key];
      failed.add(key);
    }
  }
}

export function resetArtSession() {
  queue.length = 0;
  failed.clear();
  disabledReason = null;
}

/** An <img> for generated art, or null. Painted images fill their box; drawn SVG keeps its proportions. */
export function artImg(kind, subject, cls = '') {
  const url = artUrl(kind, subject);
  if (!url) return null;
  return `<img class="art-img ${url.endsWith('.svg') ? 'ink' : 'paint'} ${cls}" src="${url}" alt="" draggable="false" loading="lazy" data-art-key="${artKey(kind, subject).replace(/"/g, '&quot;')}">`;
}
